import Foundation

/// Faithful Arabic localizations of the catalog's short English reflections.
/// Qur'anic quotations remain quotations; explanatory text does not present
/// itself as tafsir or as a substitute for qualified personal guidance.
enum ArabicReflections {
    static let bySituationID: [String: String] = [
        "beforeMarriage": "هذا دعاء عباد الرحمن: «رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ». فقبل أن يبدأ الزواج، يعلّمنا القرآن أن نسأل الله زوجًا وأسرةً تقرّ بهما أعيننا.",
        "lookingForSpouse": "يأمر الله المجتمع بإعانة غير المتزوجين على الزواج، ويقرن ذلك بوعده: «إِن يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ». فطلب الزواج صونًا للعفة مرتبط بوعد الله بالرزق من فضله.",
        "choosingSpouse": "تقدّم هذه الآية الإيمان على كل معيار دنيوي، وتقرر أن العبد المؤمن خير «وَلَوْ أَعْجَبَكُمْ». قد يلفت الجمال والمال والمكانة النظر، لكن القرآن يوجّه الاختيار إلى الإيمان.",
        "waitingForTiming": "نزلت هذه الآية في سياق القتال، لا في سياق الزواج أو التأخر. ومبدؤها الأوسع هو محدودية علم الإنسان؛ فنحن لا نرى دائمًا تمام الخير أو الضرر فيما نريده. وهي تدعو إلى التواضع والثقة بالله، من غير أن تعد بأن تأخرًا بعينه سينتهي إلى نتيجة بعينها.",
        "worriedNeverMarry": "ترد هذه الكلمات ضمن توجيهات الله في الطلاق والعدّة. وهي تقرر وعدًا عامًا بعناية الله بمن يتقيه ويتوكل عليه، ولا تضمن زواجًا في وقت محدد. تمسّك بالوعد من غير أن تحوّله إلى تنبؤ.",
        "strugglingPatience": "الصبر هنا ليس انتظارًا سلبيًا؛ فالآية تقرنه بالصلاة بوصفهما وسيلتين عمليتين للاستعانة، وتختم بوعد المعية: «إِنَّ اللَّهَ مَعَ الصَّابِرِينَ».",

        "peaceInMarriage": "يعدّ الله رابطة الزواج من آياته، ويصف غايتها بثلاثة معانٍ: السكون، والمودة، والرحمة. فالسكينة في الزواج ليست أمرًا عارضًا، بل هي من المقاصد التي جعلها الله فيه.",
        "treatSpouseKindly": "«وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ». ثم تمضي الآية أبعد من ذلك: «فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا». فالإحسان في العشرة مأمور به، وليس مشروطًا بالمشاعر.",
        "becomeBetterSpouse": "يشمل الأمر بالمعاشرة بالمعروف الكلام، والنفقة، والصبر، والصحبة. وقال النبي ﷺ: «خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ» (رواه الترمذي)، ومن هذه الآية يبدأ ذلك المعيار.",
        "speakKindly": "«وَقُل لِّعِبَادِي يَقُولُوا الَّتِي هِيَ أَحْسَنُ»، لأن الشيطان ينزغ بين الناس. توضّح الآية أثر الكلمات: فالقول القاسي يفتح بابًا للشيطان، والقول الأحسن يغلقه.",
        "decidingTogether": "خوطب النبي ﷺ نفسه بهذا: لو كان فظًا غليظ القلب «لَانفَضُّوا مِنْ حَوْلِكَ»، وأُمر أن يشاورهم في الأمر. فالرفق والشورى هما نموذج القرآن في القيادة، ومن ذلك داخل البيت.",
        "fairnessInMarriage": "«كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَىٰ أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ». فالعدل في القرآن لا يميل مع المحبة أو المصلحة الذاتية، حتى داخل بيتك.",
        "rebuildingTrust": "ومن صفات المؤمنين المفلحين: «وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ». وتُبنى الثقة من جديد على النحو الذي تصفه الآية: بحفظ كل أمانة والوفاء بكل عهد، باستمرار.",
        "duaForFamily": "يقول عباد الرحمن: «رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا». إنه دعاء للأسرة التي لديك، وللأثر الذي تتركه من بعدك.",
        "feelingDistant": "تسمّي الآية السكينة والمودة والرحمة آياتٍ في الزواج. وعندما يظهر التباعد، تقدم هذه الكلمات معيارًا للرجوع إليه بالحوار الصادق والرعاية والاستعانة بأهل الاختصاص؛ لكنها لا تضمن أن كل علاقة يمكن أو ينبغي أن تستمر بلا تغيير.",

        "marriageProblems": "تضع الآية مسارًا عند الشقاق الزوجي الشديد: حَكَمًا موثوقًا من كل أسرة، ومحاولة صادقة للإصلاح. ولا تكون الوساطة مناسبة عند وجود خطر أو إكراه؛ فالسلامة والاستعانة بجهة مؤهلة أولًا. ولا يجوز فرض الصلح على أحد الطرفين.",
        "constantlyArguing": "«إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ». فالزوجان المؤمنان، قبل كل شيء، مؤمنان، والإصلاح بين المؤمنين مأمور به، ثم يأتي قوله تعالى: «وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ».",
        "spouseWrongedYou": "تثبت الآية أولًا حق الانتصاف بقدر المظلمة من غير تجاوز، ثم تندب إلى العفو المقترن بإصلاح حقيقي. والعفو لا يوجب إعادة فتح الأبواب، ولا إلغاء الحدود، ولا مصالحة غير آمنة. اطلب الحماية والدعم المتخصص إذا كان الأذى مستمرًا.",
        "loweringAnger": "في وصف أهل الجنة: «وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ»، ثم تقول الآية: «وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ». فكظم الغيظ من الصفات التي قرن الله بها محبته.",
        "forgivingSpouse": "نزلت حين حلف أبو بكر أن يقطع النفقة عن قريب أساء إلى أسرته (صحيح البخاري). فقال الله: «وَلْيَعْفُوا وَلْيَصْفَحُوا ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ». فقال أبو بكر إنه يحب أن يغفر الله له، وأعاد إليه النفقة.",
        "temptedToDivorce": "بيّنت عائشة رضي الله عنها أن هذه الآية تتعلق بزوجين يتراضيان بحرية على شروط عندما يخشى أحدهما الإعراض أو الفراق (صحيح البخاري، 5206). وقوله تعالى: «وَالصُّلْحُ خَيْرٌ» لا يبرر الضغط أو الحرمان أو تسوية غير آمنة؛ فلا بد أن يكون كل اتفاق مختارًا اختيارًا حقيقيًا.",
        "marriageTested": "يخبر الله أن الابتلاءات ستأتي «بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوَالِ وَالْأَنفُسِ وَالثَّمَرَاتِ»، ثم يسمّي الاستجابة التي تنال صلواته ورحمته: «إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ».",
        "afraidWontLast": "تسمّي الآية الخوف من الفقد نفسه: «وَلَنَبْلُوَنَّكُم بِشَيْءٍ مِنَ الْخَوْفِ». والبشرى ليست لمن لا يشعرون بالخوف، بل للصابرين الذين يثبتون بقول: «إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ».",
        "questioningChoice": "هذه الآية في القتال، فلا ينبغي اتخاذها دليلًا على أن زواجًا بعينه خير خفي حتمًا. ودرسها العام أدق: علمنا محدود وعلم الله كامل. اجمع هذا التواضع إلى الحقائق، والمشورة، والاستخارة، ومراعاة السلامة.",
        "trustingPlan": "تتناول هذه الآية القتال في سياقها الأصلي. ومن حيث المبدأ العام، تذكّرنا بأن رغباتنا وعلمنا محدودان. والثقة بالله تقترن بالعمل المسؤول والمشورة؛ فالآية لا تصف كل ظرف مؤلم بأنه خير، ولا تلزم بالبقاء في الأذى.",
        "trustingTiming": "السياق المباشر للآية هو القتال. ويمكن لكلماتها الختامية، «وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ»، أن تثبّت القلب حين تلتبس النتائج، لكنها لا تعد بتاريخ أو نتيجة محددة. والصبر هنا عبادة، وعمل حكيم، وقبول لما خرج عن علمك.",
        "stayOrLeave": "يوصي القرآن عند الشقاق الزوجي الشديد بتحكيم موثوق من الجانبين. وهذه خطوة ممكنة، لا أمر بالبقاء في خطر. فإذا وُجد عنف أو إكراه أو خوف على السلامة، فتواصل أولًا مع جهة الدعم المحلية المناسبة. ولمعرفة الأحكام واتخاذ قرار بهذه الأهمية، استشر جهة مستقلة مؤهلة.",

        "raisingChildren": "«يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا». فالتربية في القرآن رعاية ومسؤولية، ودين البيت أمانة يحملها الزوجان معًا.",
        "prayingForChildren": "دعاء إبراهيم عليه السلام: «رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ». لم يسأل ولدًا فحسب، بل سأل الصلاح فيه، فبشّره الله بغلام حليم.",
        "infertility": "دعا زكريا عليه السلام ربه في الكبر: «رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ»، فقال الله: «فَاسْتَجَبْنَا لَهُ وَوَهَبْنَا لَهُ يَحْيَىٰ وَأَصْلَحْنَا لَهُ زَوْجَهُ». ثم تصف الآيات من استجاب لهم: «إِنَّهُمْ كَانُوا يُسَارِعُونَ فِي الْخَيْرَاتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا».",
        "spouseAway": "قال يعقوب عليه السلام، وهو يتألم لفراق أحبته: «إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ». فالاشتياق ليس ضعفًا في الإيمان؛ يعرض القرآن نبيًا يحمله، ويبيّن إلى من حمل شكواه.",
        "divorceUnavoidable": "حتى هنا يشرّع القرآن بدقة وكرامة: إحصاء العدّة، وألا تُخرج المطلقة من بيتها. ويترك بابًا مفتوحًا: «لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا». وفي أي إجراءات فعلية، استشر عالمًا مؤهلًا.",
        "afterDivorce": "ليس من المصادفة أن أشهر وعد قرآني بالفرج، وبالمخرج والرزق من حيث لا يُحتسب، يأتي في سورة الطلاق. لقد نزلت هذه الكلمات في سياق هذا الجرح نفسه.",
        "grievingSpouse": "«إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ». وعلى من يقولونها عند المصيبة صلوات من الله ورحمة. فالحزن الذي يُستقبل بهذه الكلمات حزن يكرمه الله بنفسه.",

        "needGuidance": "الدعاء المحوري في الفاتحة، «اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ»، يُتلى في كل ركعة من كل صلاة. تُطلب الهداية كل يوم لأننا نحتاجها كل يوم، والله نفسه علّمنا كلمات السؤال.",
        "imanLow": "«أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَزَلَ مِنَ الْحَقِّ». إنه نداء رفيق للمؤمنين حين بدأت قلوبهم تفتر، ودعوة إلى العودة لا حكم بالرفض.",
        "salahConnection": "تفتتح السورة بربط الفلاح بالصلاة بحضور القلب: فالمؤمنون المفلحون هم «الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ». والخشوع أول صفاتهم المذكورة، وهو ما يُسأل الله ويُنَمّى صلاة بعد صلاة.",
        "hardToPray": "تعترف الآية نفسها بالمشقة: استعينوا بالصبر والصلاة، «وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ». لا يصوّر القرآن الصلاة كأنها بلا مجاهدة؛ بل يسمّي الصعوبة ويدل على طريق تجاوزها.",
        "losingFocus": "تقيس سورة العصر الحياة بالزمن نفسه: فالناس جميعًا في خسر إلا من آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر. ثلاث آيات قصيرة تعيد ضبط الغاية الحقيقية من يومك.",
        "forgettingBlessings": "أعلن ربك بنفسه: «لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ». فالشكر في القرآن ليس مجرد أدب، بل هو الشرط المصرح به للزيادة.",
        "strugglingGrateful": "الشكر مرتبط بوعد مؤكد أعلنه الله: «لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ». ابدأ بتسمية نعمة واحدة في كل مرة؛ فالزيادة تتبع الشكر، لا العكس.",
        "fightingTemptation": "للذين يبذلون جهدهم ابتغاء مرضاته: «وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا». الوعد لمن هو في قلب المجاهدة؛ فالسعي نفسه يقرّب هداية الله، وتختم الآية: «وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ».",
        "madeAMistake": "لعلها أوسع أبواب القرآن: «قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ». خطاب لمن أخطؤوا، بأرق نداء: «يَا عِبَادِيَ».",
        "forgiveYourself": "الآية في رحمة الله والدعوة إلى التوبة، وليست تأسيسًا لمفهوم مستقل يسمى «مسامحة النفس». إنها تنهى عن اليأس بعد الذنب: اعترف بالخطأ، وعُد إلى الله، وأصلح ما تستطيع، ولا تتعامل مع شعورك بالخزي كأنه أعظم من رحمته.",
        "sameSin": "تقول الآية إن الله يغفر الذنوب جميعًا، وتخاطب من يخشون أن ذنوبهم أكثر أو أشد تكرارًا من أن تُغفر. عُد في كل مرة؛ فرحمة الله لا تنفد مهما تكررت توبتك.",
        "selfControl": "تُوعَد الجنة لمن خاف مقام ربه «وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ». فلا يُعرض ضبط النفس بوصفه حرمانًا، بل مبادلة: شهوة تُكف الآن، ومأوى يدوم.",

        "scaredOfFuture": "«قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا». ليس في المستقبل شيء لم يكتبه لك من قبل مولاك: «وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ».",
        "afraidOfFailure": "ما قُدِّر أن يصيبك لم يكن ليخطئك. يعمل المؤمن ويبذل كامل وسعه، ثم يطمئن ويفوّض النتيجة إلى من قدّرها؛ فهو «مَوْلَىٰنَا».",
        "worriedTomorrow": "تفتح التقوى مخرجًا حين لا يبدو أي مخرج، ويأتي الرزق «مِنْ حَيْثُ لَا يَحْتَسِبُ». ثم يختم السياق الوعد: «وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ».",
        "feelAlone": "يصف الله قربه بأنه «أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ»؛ أقرب من الوريد في عنقك، وعالم بما توسوس به نفسك. قد تشعر أن الناس لا يرونك، لكنك لم تغب عن علمه لحظة واحدة.",
        "tooManyBurdens": "«لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا». مَن خلقك قدّر ما تحمله على قدر طاقتك، والآية ذاتها تعلّمك الدعاء إليه أن يخففه عنك.",
        "disappointed": "يعقوب عليه السلام، بعد أعوام من الفقد، ما يزال يأمر أبناءه أن يذهبوا ويتحرّوا، ويقول لهم: «وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ». في القرآن، ليس الرجاء سذاجة؛ بل موقف من صميم الإيمان.",
        "movingOn": "مرتين متتابعتين: «فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا»، ثم «إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا». وبعد العسر يأتي التوجيه لما هو آتٍ: «فَإِذَا فَرَغْتَ فَٱنصَبْ ۝ وَإِلَىٰ رَبِّكَ فَٱرْغَب».",
        "everyoneAhead": "«وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ». لقد قُسِّم نصيب كل إنسان بتقدير. ثم تحوّل الآية ألم المقارنة إلى دعاء مباشر لنفسك: «وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ».",
        "someoneHurtsYou": "«وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ». فالصبر على الأذى ليس ضعفًا؛ بل يعدّه القرآن من أعظم صور قوة العزم.",
        "needToForgive": "«وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ». تربط الآية عفوك عن الناس برجائك في عفو الله عنك؛ فليكن عفوك على قدر رجائك في أن يُعفى عنك.",
        "afraidPeopleThink": "حين حاول الناس تخويف المؤمنين، لم يزدهم ذلك إلا إيمانًا، وقالوا: «حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ». فلا رضا يعلو في الميزان على رضا الله.",
        "feelingInsecure": "«وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ». نزلت بعد جراح أُحد، فتعيد تثبيت قوم تزلزلوا على أساس الإيمان، لا على أساس الظروف.",
        "facingRejection": "تستحضر الآية من سبقوكم وقد زُلزلوا حتى قال الرسول نفسه: «مَتَىٰ نَصْرُ ٱللَّهِ». ويبقى الجواب فوق كل باب مغلق: «أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ».",

        "worriedAboutRizq": "وُعِد المتقي المتوكل بالرزق «مِنْ حَيْثُ لَا يَحْتَسِبُ»، ثم جاء التقرير: «قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا». يسير الرزق مع التقوى في مسالك لا تملك رسمها.",
        "strugglingFinancially": "أمر نوح عليه السلام قومه أن يستغفروا ربهم، فيرسل السماء عليهم مدرارًا و«يُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ». يبيّن القرآن الاستغفار بابًا من أبواب الرزق.",
        "hesitantCharity": "«مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً». فالصدقة في القرآن ليست خسارة؛ بل قرض لله يضاعف جزاءه أضعافًا كثيرة.",
        "comparingFinances": "«إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ». تختلف الأنصبة بحسب علمه بعباده، لا بحسب قيمتهم، فالآية تختم بأنه كان بعباده «خَبِيرًۢا بَصِيرًا».",
        "financialBurdens": "تؤكد الآية عدل الله، وتُختتم بدعاء ألا نُحمَّل ما لا طاقة لنا به. وينبغي ألا تُستخدم للتهوين من المعاناة أو لإخبار أحد بأنه ملزم بتحمل الضرر وحده. اطلب مع هذا الدعاء عونًا عمليًا، ومشورة من مختص بشؤون الديون، وسندًا من المجتمع.",
        "moneyStress": "«وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ». مخلوقات لا تُحصى لا تملك مدخرات أصلًا، ومع ذلك يرزقها كل يوم الرزّاق نفسه الذي يرزقك.",
        "afraidToSpend": "كل ما تنفقه في سبيله، «فَهُوَ يُخْلِفُهُۥ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ». الإنفاق لله ليس نقصًا؛ والخَلَف وعد من الرزّاق نفسه.",
        "tomorrowRizq": "يقول الله إنه لو بسط الرزق لعباده بلا حد لبغوا في الأرض، «وَلَـٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ». ما في يدك اليوم مقدّر بعلم، لا محجوب عنك إهمالًا.",
        "workNoResults": "«وَأَن لَّيْسَ لِلْإِنسَـٰنِ إِلَّا مَا سَعَىٰ». لا يضيع جهد صادق في ميزان الله، حتى في الفترات التي لم تظهر فيها النتائج بعد.",
        "heartAttachedMoney": "«ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱلْبَـٰقِيَـٰتُ ٱلصَّـٰلِحَـٰتُ خَيْرٌ عِندَ رَبِّكَ». جملة واحدة تعيد ترتيب ما يقبض عليه القلب بقوة وما يتركه برفق.",
        "barakahInWealth": "يأتي وعد الزيادة عقب الشكر، لكن الآية لا تحدد أن تكون الزيادة مالًا. فقد تظهر في الإيمان، أو القناعة، أو النفع، أو غير ذلك مما يختاره الله. فاشكر الله من غير أن تحوّل العبادة إلى ضمان للنمو المالي.",
        "provisionDelayed": "تصف الآية الله بأنه «ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ». وهي تثبّت التوكل عليه حين يبدو الرزق بطيئًا، من دون أن تخبرنا متى يأتي الفرج أو في أي صورة. ويشمل التوكل السعي الحلال، والتخطيط، وطلب العون.",
        "salaryNotEnough": "«نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا». الأرقام في بيان الراتب ليست الحساب الكامل لما يسوقه الله إليك؛ فالمعيشة يدبّرها هو، لا السوق وحده.",
        "scaredStartBusiness": "«فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ». يرسم القرآن خطوات الإقدام على مشروع: شاور، وتدبّر، واعزم، ثم فوّض النتيجة إليه.",
        "stuckFinancially": "تتحدث هذه الآية عن الحال الأخلاقية لقوم وعن سنن الله في المجتمعات؛ وليست معادلة تعد الفرد بتغيّر وضعه المالي. وقد تدعو مع ذلك إلى مراجعة النفس بصدق، بينما قد تستلزم العوائق المالية الواقعية أيضًا مشورة خارجية ودعمًا يعالج الأسباب البنيوية.",
        "jealousOfSuccess": "«وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ». ثم تحوّل الآية الحسد إلى دعاء: «وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ». خزائن الله لا تنقص بما أعطاهم.",
        "providingForFamily": "تنهى الآية عن قتل الأولاد خشية الفقر، وتعلن أن الله يرزق الأبناء والوالدين. موضوعها المباشر حرمة الحياة، لا وعد بأن تكاليف الأسرة ستختفي. فخذ منها ما يدفع اليأس، مع وضع ميزانية، وطلب الدعم الحلال، والوفاء بمسؤوليات الأسرة.",
        "afraidToRisk": "قيلت هذه الكلمات لبني إسرائيل في شأن دخول الأرض المقدسة، لا في الإقدام على مخاطرة مالية. ودرسها الأوسع هو شجاعة التوكل بعدما يتضح المسار المشروع. أما العمل التجاري أو الاستثمار فما يزال يحتاج إلى التحقق من التفاصيل، والمشاورة، وتقييم صادق للضرر.",
        "majorFinancialDecision": "سياق الآية المباشر هو القتال. وتذكّرنا بمعنى عام، وهو أن ما نفضله لا يقوم مقام العلم الكامل؛ وهي لا تختار استثمارًا نيابة عنك. تحرَّ الحقائق، وتجنب المعاملات المحرمة، واستشر أهل الاختصاص، وصلِّ الاستخارة، واتخذ قرارًا مسؤولًا.",
        "impatientForResults": "«ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ». الوعد هنا بمعية الله أثناء الانتظار، لا بالثواب عند نهايته فحسب.",
        "everyoneAheadDuha": "تواسي هذه الآية النبي ﷺ وتوجّه النظر إلى الآخرة؛ وليست تنبؤًا بتقدم مهني أو مالي. وحين تحصر المقارنة رؤيتك في المحطات الدنيوية، تعيد إليك المقياس الذي يُوزن به النجاح الباقي.",
        "payingBills": "ترد هذه الكلمات في أثناء أحكام الطلاق، وتعد بعناية الله لمن يتقيه ويتوكل عليه. وهي لا تعد بسداد فاتورة محددة في موعد محدد. اجمع بين التوكل والتواصل المبكر مع الدائنين، وإعداد الميزانية، وطلب عون المجتمع.",
        "stressedAboutDebt": "«لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا». تعامل مع الدَّين دفعة بعد دفعة، مستعينًا بالدعاء الذي تعلّمك إياه الآية: «رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ».",
        "losingJob": "«مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَـٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ». ما من شيء في رزقك يقع بلا تقدير؛ فقد كُتب، وكذلك ما يأتي بعده.",
        "savingsLow": "«وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ». رصيد الحساب ليس مصدر الرزق؛ إنما المصدر هو الرزّاق، ولم يكن رزقه لك قط مرهونًا بمدخراتك.",
    ]

    /// IDs present in the live catalog that do not yet have Arabic copy.
    static var missingSituationIDs: [String] {
        let expected = Set(SituationCatalog.all.map(\.id))
        return expected.subtracting(Set(bySituationID.keys)).sorted()
    }

    /// Translation keys that no longer correspond to a live catalog entry.
    static var unexpectedSituationIDs: [String] {
        let expected = Set(SituationCatalog.all.map(\.id))
        return Set(bySituationID.keys).subtracting(expected).sorted()
    }

    static var isComplete: Bool {
        bySituationID.count == SituationCatalog.all.count
            && missingSituationIDs.isEmpty
            && unexpectedSituationIDs.isEmpty
    }
}

extension Situation {
    func localizedWhyNote(_ language: AppLanguage) -> String {
        switch language {
        case .english:
            return whyNote
        case .arabic:
            return ArabicReflections.bySituationID[id] ?? whyNote
        }
    }
}
